// line/column position implied by the characters read so far.
export class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof(offset = 0) {
    return this.i + offset >= this.chars.length
  }

  peek(offset = 0) {
    const j = this.i + offset
    return j < this.chars.length ? this.chars[j] : undefined
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }
}
"}

