// Consumes a maximal run of digits (per isDigitFn) allowing a single
// underscore between two digits of the run, and nowhere else. Returns the
// consumed text and how many digits (not counting underscores) it held.
function consumeDigitRun(sc, isDigitFn) {
  let text = ''
  let count = 0
  if (!isDigitFn(sc.peek())) return { text, count }
  for (;;) {
    const c = sc.peek()
    if (isDigitFn(c)) {
      text += sc.advance()
      count++
    } else if (c === '_' && count > 0 && isDigitFn(sc.peek(1))) {
      text += sc.advance()
    } else {
      break
    }
  }
  return { text, count }
}

