  const startPos = sc.pos()
  let text = ''
  let ok

  const c0 = sc.peek()
  const c1 = sc.peek(1)
  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isHexDigit)
    text += digits.text
    ok = digits.count > 0
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isBinDigit)
    text += digits.text
    ok = digits.count > 0
  } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isOctDigit)
    text += digits.text
    ok = digits.count > 0
  } else {
    const intDigits = consumeDigitRun(sc, isDigit)
    text += intDigits.text
    ok = true
    if (sc.peek() === '.' && isDigit(sc.peek(1))) {
      text += sc.advance()
      const fracDigits = consumeDigitRun(sc, isDigit)
      text += fracDigits.text
    }
    if (
      (sc.peek() === 'e' || sc.peek() === 'E') &&
      (isDigit(sc.peek(1)) || ((sc.peek(1) === '+' || sc.peek(1) === '-') && isDigit(sc.peek(2))))
    ) {
      text += sc.advance()
      if (sc.peek() === '+' || sc.peek() === '-') text += sc.advance()
      const expDigits = consumeDigitRun(sc, isDigit)
