      if (sc.eof()) throw err(startPos, 'unterminated string')
      const ec = sc.peek()
      if (ec === 'n') {
        value += '\n'
        sc.advance()
      } else if (ec === 't') {
        value += '\t'
        sc.advance()
      } else if (ec === 'r') {
        value += '\r'
        sc.advance()
      } else if (ec === '\\') {
        value += '\\'
        sc.advance()
      } else if (ec === '"') {
        value += '"'
        sc.advance()
      } else if (ec === '0') {
        value += '\0'
        sc.advance()
