const ONE = new Set('+-*/%=<>!(){}[],;.'.split(''))

export function matchPunct(sc) {
  const c1 = sc.peek()
  const c2 = sc.peek(1)
  if (c1 !== undefined && c2 !== undefined && TWO.has(c1 + c2)) {
    sc.advance()
    sc.advance()
    return c1 + c2
  }
  if (c1 !== undefined && ONE.has(c1)) {
    sc.advance()
    return c1
  }
  return null
