import { err, LexError } from './errors.js'
import { isLetter, isDigit, isIdentChar } from './chars.js'
import { skipLineComment, skipBlockComment } from './comments.js'
import { scanNumber } from './numbers.js'
import { scanString, scanRawString } from './strings.js'
import { matchPunct } from './punct.js'

export { LexError }

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

function scanIdent(sc) {
  const pos = sc.pos()
  let text = ''
  while (!sc.eof() && isIdentChar(sc.peek())) text += sc.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, pos }
}

export function scan(source) {
  const sc = new Scanner(source)
  const tokens = []
  while (!sc.eof()) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '/') {
      skipLineComment(sc)
      continue
    }
    if (c === '/' && sc.peek(1) === '*') {
      skipBlockComment(sc)
      continue
    }
    if (c === '"') {
      tokens.push(scanString(sc))
      continue
    }
    if (c === 'r' && sc.peek(1) === '"') {
      tokens.push(scanRawString(sc))
      continue
    }
    if (isLetter(c) || c === '_') {
      tokens.push(scanIdent(sc))
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(sc))
      continue
    }
    const pos = sc.pos()
    const p = matchPunct(sc)
    if (p) {
      tokens.push({ kind: 'punct', text: p, pos })
      continue
    }
    throw err(pos, 'unexpected character ' + c)
  }
  return tokens
}
"}

{"file_path":"src/format.js","content":"const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

export function formatTokens(tokens) {
  let out = ''
  for (const t of tokens) out += `${t.pos.line}:${t.pos.col} ${t.kind} ${t.text}\n`
  return out
}

export function formatStats(tokens) {
  const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
  for (const t of tokens) counts[t.kind]++
  let out = ''
  for (const k of STAT_KINDS) out += `${k} ${counts[k]}\n`
  out += `total ${tokens.length}\n`
  return out
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan, LexError } from './lexer.js'
import { formatTokens, formatStats } from './format.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exitCode = 2
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    usageError()
    return
  }
  const mode = args[0]
  const text = await readStdin()

  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.reason}\n`)
      process.exitCode = 2
      return
    }
    throw e
  }

  const out = mode === 'tokens' ? formatTokens(tokens) : formatStats(tokens)
  process.stdout.write(out)
}

main().catch((e) => {
  process.stderr.write(`error: ${e && e.message ? e.message : String(e)}\n`)
  process.exitCode = 2
})
"}

